import{_ as e,r as s,o,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Контроллер импорта и экспорта - October CMS - 3.x","titleTemplate":false,"description":"Добавляет функции импорта и экспорта на страницу.","frontmatter":{"subtitle":"Добавляет функции импорта и экспорта на страницу."},"headers":[{"level":2,"title":"Настройка поведения","slug":"настроика-поведения","link":"#настроика-поведения","children":[{"level":3,"title":"Страница импорта","slug":"страница-импорта","link":"#страница-импорта","children":[]},{"level":3,"title":"Страница экспорта","slug":"страница-экспорта","link":"#страница-экспорта","children":[]},{"level":3,"title":"Параметры формата","slug":"параметры-формата","link":"#параметры-формата","children":[]}]},{"level":2,"title":"Представления импорта и экспорта","slug":"представления-импорта-и-экспорта","link":"#представления-импорта-и-экспорта","children":[{"level":3,"title":"Представление импорта","slug":"представление-импорта","link":"#представление-импорта","children":[]},{"level":3,"title":"Представление экспорта","slug":"представление-экспорта","link":"#представление-экспорта","children":[]}]},{"level":2,"title":"Интеграция с поведением списка","slug":"интеграция-с-поведением-списка","link":"#интеграция-с-поведением-списка","children":[]}],"relativePath":"3.x/ru/extend/importexport/importexport-controller.md","filePath":"3.x/ru/extend/importexport/importexport-controller.md"}'),u={name:"3.x/ru/extend/importexport/importexport-controller.md"};function i(d,a,k,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Контроллер импорта и экспорта",-1)),n(p),a[1]||(a[1]=r(`<p>Класс <code>Backend\\Behaviors\\ImportExportController</code> — это поведение контроллера, предоставляющее функции для импорта и экспорта данных. Поведение предоставляет две страницы: Импорт и Экспорт. Страница Импорт позволяет пользователю загрузить CSV-файл и сопоставить столбцы с базой данных. Страница Экспорт делает обратное и позволяет пользователю скачать столбцы из базы данных в виде CSV-файла. Поведение предоставляет действия контроллера <code>import()</code> и <code>export()</code>.</p><p>Конфигурация поведения импорта и экспорта определяется в двух частях, каждая часть зависит от специального класса модели вместе с файлом определения списка и полей формы. Для использования поведения вы должны добавить его в свойство <code>$implement</code> класса контроллера. Также должно быть определено свойство класса <code>$importExportConfig</code>, и его значение должно ссылаться на YAML-файл, используемый для настройки свойств поведения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Shop<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Products</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ImportExportController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$importExportConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_import_export.yaml&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// [...]</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="настроика-поведения"><a href="#настроика-поведения" class="header-anchor">#</a> Настройка поведения</h2><p>Файл конфигурации, указанный в свойстве <code>$importExportConfig</code>, определяется в формате YAML. Файл должен быть размещён в <a href="./../system/views.html">директории представлений</a> контроллера. Ниже приведён пример файла конфигурации.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_import_export.yaml</span>
<span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml

<span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml
</code></pre></div><p>Ниже перечислены необязательные свойства конфигурации. Определяйте их, если хотите, чтобы поведение поддерживало страницу импорта или страницу экспорта, или обе.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>defaultRedirect</strong></td><td>используется как резервная страница перенаправления, когда конкретная страница перенаправления не определена.</td></tr><tr><td><strong>import</strong></td><td>массив конфигурации или ссылка на файл конфигурации для страницы Импорта.</td></tr><tr><td><strong>export</strong></td><td>массив конфигурации или ссылка на файл конфигурации для страницы Экспорта.</td></tr><tr><td><strong>defaultFormatOptions</strong></td><td>массив конфигурации или ссылка на файл конфигурации для параметров формата CSV по умолчанию.</td></tr></tbody></table></div><h3 id="страница-импорта"><a href="#страница-импорта" class="header-anchor">#</a> Страница импорта</h3><p>Для поддержки страницы Импорта добавьте следующую конфигурацию в YAML-файл.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberimport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>Следующие свойства конфигурации поддерживаются для страницы Импорта.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>заголовок страницы, может ссылаться на <a href="./../system/localization.html">строку локализации</a>.</td></tr><tr><td><strong>list</strong></td><td>определяет доступные столбцы списка для импорта.</td></tr><tr><td><strong>form</strong></td><td>предоставляет дополнительные поля, используемые как параметры импорта, необязательно.</td></tr><tr><td><strong>redirect</strong></td><td>страница перенаправления после завершения импорта, необязательно.</td></tr><tr><td><strong>permissions</strong></td><td>разрешения пользователя, необходимые для выполнения операции, необязательно.</td></tr></tbody></table></div><h3 id="страница-экспорта"><a href="#страница-экспорта" class="header-anchor">#</a> Страница экспорта</h3><p>Для поддержки страницы Экспорта добавьте следующую конфигурацию в YAML-файл.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberexport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>Следующие свойства конфигурации поддерживаются для страницы Экспорта:</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>заголовок страницы, может ссылаться на <a href="./../system/localization.html">строку локализации</a>.</td></tr><tr><td><strong>fileName</strong></td><td>имя файла для экспортируемого файла без расширения. По умолчанию: <code>export</code></td></tr><tr><td><strong>list</strong></td><td>определяет доступные столбцы списка для экспорта.</td></tr><tr><td><strong>form</strong></td><td>предоставляет дополнительные поля, используемые как параметры экспорта, необязательно.</td></tr><tr><td><strong>redirect</strong></td><td>страница перенаправления после завершения экспорта, необязательно.</td></tr><tr><td><strong>useList</strong></td><td>установите в true или значение определения списка для включения интеграции со списками. По умолчанию: <code>false</code>.</td></tr></tbody></table></div><h3 id="параметры-формата"><a href="#параметры-формата" class="header-anchor">#</a> Параметры формата</h3><p>Для переопределения параметров формата по умолчанию добавьте следующую конфигурацию в YAML-файл:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">defaultFormatOptions</span><span class="token punctuation">:</span>
    <span class="token key atrule">fileFormat</span><span class="token punctuation">:</span> json
</code></pre></div><p>Следующие свойства конфигурации (все необязательные) поддерживаются для параметров формата, включая их применимый тип формата.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th><th>Формат</th></tr></thead><tbody><tr><td><strong>fileFormat</strong></td><td>Формат файла: <code>json</code>, <code>csv</code> или <code>csv_custom</code>, по умолчанию: <code>json</code>.</td><td></td></tr><tr><td><strong>customJson</strong></td><td>Использовать пользовательский формат для типа <code>json</code>.</td><td>JSON</td></tr><tr><td><strong>firstRowTitles</strong></td><td>Первая строка содержит заголовки, только импорт.</td><td>CSV</td></tr><tr><td><strong>delimiter</strong></td><td>Символ-разделитель.</td><td>CSV (Custom)</td></tr><tr><td><strong>enclosure</strong></td><td>Символ-ограничитель.</td><td>CSV (Custom)</td></tr><tr><td><strong>escape</strong></td><td>Символ экранирования.</td><td>CSV (Custom)</td></tr><tr><td><strong>encoding</strong></td><td>Кодировка файла, только импорт.</td><td>CSV (Custom)</td></tr></tbody></table></div><h2 id="представления-импорта-и-экспорта"><a href="#представления-импорта-и-экспорта" class="header-anchor">#</a> Представления импорта и экспорта</h2><p>Для каждой функции страницы импорта и экспорта вы должны предоставить <a href="./../system/views.html">файл представления</a> с соответствующим именем — <strong>import.htm</strong> и <strong>export.htm</strong>.</p><p>Поведение импорта/экспорта добавляет два метода в класс контроллера: <code>importRender</code> и <code>exportRender</code>. Эти методы рендерят разделы импорта и экспорта согласно файлу конфигурации YAML, описанному выше.</p><h3 id="представление-импорта"><a href="#представление-импорта" class="header-anchor">#</a> Представление импорта</h3><p>Представление <strong>import.htm</strong> отображает страницу Импорта, которая позволяет пользователям импортировать данные. Типичная страница Импорта содержит хлебные крошки, сам раздел импорта и кнопки отправки. Атрибут <strong>data-request</strong> должен ссылаться на AJAX-обработчик <code>onImport</code>, предоставляемый поведением. Ниже приведено содержимое типичного файла представления import.htm.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">importRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onImportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Import records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="представление-экспорта"><a href="#представление-экспорта" class="header-anchor">#</a> Представление экспорта</h3><p>Представление <strong>export.htm</strong> отображает страницу Экспорта, которая позволяет пользователям экспортировать файл из базы данных. Типичная страница Экспорта содержит хлебные крошки, сам раздел экспорта и кнопки отправки. Атрибут <strong>data-request</strong> должен ссылаться на AJAX-обработчик <code>onExport</code>, предоставляемый поведением. Ниже приведено содержимое типичной формы export.htm.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">exportRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Export records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="интеграция-с-поведением-списка"><a href="#интеграция-с-поведением-списка" class="header-anchor">#</a> Интеграция с поведением списка</h2><p>Существует альтернативный подход к экспорту данных, который использует <a href="./../lists/list-controller.html">поведение списка</a> для предоставления данных экспорта. Для использования этой функции вы должны добавить определение <code>Backend\\Behaviors\\ListController</code> в поле <code>$implement</code> класса контроллера. Вам не нужно использовать представление экспорта, и все настройки будут взяты из списка. Вот единственная необходимая конфигурация:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Затем просто добавьте кнопку экспорта в <a href="./../lists/list-controller.html">панель инструментов списка</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/campaign/subscribers/export&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default oc-icon-download<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Export Records
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Аналогично, для добавления кнопки импорта код будет выглядеть так:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/campaign/subscribers/import&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default oc-icon-upload<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Import Records
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Если вы используете <a href="./../lists/list-controller.html">множественные определения списков</a>, вы можете указать определение списка.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> orders
    <span class="token key atrule">fileName</span><span class="token punctuation">:</span> orders.csv
</code></pre></div><p>Параметр <code>useList</code> также поддерживает расширенные свойства конфигурации.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span>
        <span class="token key atrule">definition</span><span class="token punctuation">:</span> orders
        <span class="token key atrule">raw</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Поддерживаются следующие свойства конфигурации:</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>definition</strong></td><td>определение списка, из которого берутся записи, необязательно.</td></tr><tr><td><strong>raw</strong></td><td>выводить необработанные значения атрибутов из записи, по умолчанию: false.</td></tr></tbody></table></div>`,45))])}const y=e(u,[["render",i]]);export{v as __pageData,y as default};
